"""Generate a private archive runtime and its typed consumer API."""

import hashlib
import json
from pathlib import Path

from gtwrap.serialization import discover


def generate_library(name, sources, headers, namespace_prefixes=(),
                     ignore_classes=()):
    """Return generated files indexed by basename; callers choose placement.

    C linkage gives the linker an exact export list; parameters still require
    the same C++ ABI and runtime in consumers and the library.
    """
    if not name or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-' for c in name):
        raise ValueError('library name must contain only letters, digits, _ or -')
    if not headers or any('\n' in h or '\r' in h or '>' in h for h in headers):
        raise ValueError('supply C++ headers defining the managed types')
    exports = discover(sources, namespace_prefixes, ignore_classes)
    library_id = hashlib.sha256(name.encode()).hexdigest()[:16]
    macro = f'GTWRAP_SERIALIZATION_{library_id.upper()}_API'
    building = macro + '_BUILDING'
    api_name = name + '.h'
    keys_name = name + '_keys.h'
    entries = []
    for export in exports:
        type_id = hashlib.sha256(export.cpp_type.encode()).hexdigest()[:16]
        symbol = f'gtwrap_{library_id}_{type_id}'
        entries.append(dict(cpp_type=export.cpp_type, export_name=export.name,
                            save=symbol + '_save', load=symbol + '_load'))

    api = ['// Generated by gtwrap. Do not edit.', '#pragma once',
           '#include <string>']
    api += [f'#include <{h}>' for h in headers]
    api += [f'#if defined(_WIN32) && defined({building})',
            f'#define {macro} __declspec(dllexport)',
            '#elif defined(_WIN32)', f'#define {macro} __declspec(dllimport)',
            '#else', f'#define {macro} __attribute__((visibility("default")))',
            '#endif', '']
    keys = ['// Private registration declarations.', '#pragma once',
            '#include <boost/serialization/export.hpp>', f'#include "{api_name}"']
    source = ['// Generated by gtwrap. Do not edit.',
              '// Only the typed bridge is part of this library\'s public ABI.',
              '#if defined(_WIN32)', '#include <boost/serialization/force_include.hpp>',
              '// Keep Boost singleton optimizer annotations private.',
              '#undef BOOST_DLLEXPORT', '#define BOOST_DLLEXPORT', '#endif',
              f'#define {building}',
              '#include <boost/archive/text_iarchive.hpp>',
              '#include <boost/archive/text_oarchive.hpp>',
              '#include <boost/archive/archive_exception.hpp>',
              f'#include "{keys_name}"', '#include <sstream>',
              '#include <stdexcept>', '']
    symbols = []
    for entry in entries:
        cpp_type, export = entry['cpp_type'], entry['export_name']
        save, load = entry['save'], entry['load']
        symbols += [save, load]
        api += [f'extern "C" {macro} void {save}(const {cpp_type}* value, std::string* output);',
                f'extern "C" {macro} void {load}(const std::string* input, {cpp_type}* value);']
        if export != cpp_type:
            keys.append(f'typedef {cpp_type} {export};')
        keys.append(f'BOOST_CLASS_EXPORT_KEY({export})')
        source.append(f'BOOST_CLASS_EXPORT_IMPLEMENT({export})')
    for entry in entries:
        cpp_type, save, load = entry['cpp_type'], entry['save'], entry['load']
        source.append(f'''
extern "C" {macro} void {save}(const {cpp_type}* value, std::string* output) {{
  try {{
    std::ostringstream stream;
    {{ boost::archive::text_oarchive archive(stream); archive << *value; }}
    *output = stream.str();
  }} catch (const boost::archive::archive_exception& error) {{
    throw std::runtime_error(error.what());
  }}
}}

extern "C" {macro} void {load}(const std::string* input, {cpp_type}* value) {{
  try {{
    std::istringstream stream(*input);
    boost::archive::text_iarchive archive(stream);
    archive >> *value;
  }} catch (const boost::archive::archive_exception& error) {{
    throw std::runtime_error(error.what());
  }}
}}''')
    return {
        api_name: '\n'.join(api) + '\n',
        keys_name: '\n'.join(keys) + '\n',
        name + '.cpp': '\n'.join(source) + '\n',
        name + '.json': json.dumps(dict(version=1, header=api_name,
                                       entries=entries), indent=2) + '\n',
        name + '.map': '{ global:\n' + ''.join(f'  {s};\n' for s in symbols)
                       + 'local: *;\n};\n',
        name + '.exports': ''.join(f'_{s}\n' for s in symbols),
    }


def write_library(directory, files):
    """Write every output, including unchanged ones, to satisfy build timestamps."""
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    for name, content in files.items():
        (directory / name).write_text(content, encoding='utf-8')
